 check(getTargetContext().getPackageName().equals("br.com.lealinfo.vidraceiro.ambiente37"),"same QA37 package for update");check(new File(getTargetContext().getFilesDir(),"upgrade37-marker").exists(),"0.3.8 update retains app files");
 a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check("access".equals(a.page)&&!AccessControl.ready(),"login gate before any business data");
